1164	<script>
1165	(function(){
1166	'use strict';
1167	var root=document.documentElement, deck=document.getElementById('deck');
1168	var slides=[].slice.call(document.querySelectorAll('.slide'));
1169	var TOTAL=slides.length, idx=0;
1170	var counter=document.getElementById('counter'), pbar=document.getElementById('pbar'), brand=document.getElementById('brand');
1171	
1172	/* ---------- palco: escala fixa 1600x900, ou leitura vertical em telas estreitas ---------- */
1173	function isMobile(){ return window.innerWidth < 820 || (window.innerWidth < 1000 && window.innerHeight > window.innerWidth); }
1174	function fitStage(){
1175	  if (isMobile()){ root.classList.add('mobile'); deck.style.transform='none'; return; }
1176	  root.classList.remove('mobile');
1177	  var pad = 22;
1178	  var k = Math.min((window.innerWidth-pad)/1600,(window.innerHeight-pad)/900);
1179	  deck.style.transform='translate(-50%,-50%) scale('+k+')';
1180	}
1181	window.addEventListener('resize',fitStage);
1182	
1183	/* ---------- navegação ---------- */
1184	var dotsBox=document.getElementById('dots'), ovg=document.getElementById('ovg');
1185	slides.forEach(function(s,i){
1186	  var d=document.createElement('button'); d.className='dot'+(s.dataset.divider?' sec':''); d.setAttribute('aria-label','Ir ao slide '+(i+1));
1187	  d.title=s.dataset.title||''; d.addEventListener('click',function(){goTo(i,i<idx);}); dotsBox.appendChild(d);
1188	  var c=document.createElement('button'); c.className='ovc';
1189	  c.innerHTML='<span class="on2">'+(i+1<10?'0':'')+(i+1)+'</span><span class="ot"></span>';
1190	  c.querySelector('.ot').textContent=s.dataset.title||'';
1191	  c.addEventListener('click',function(){toggleOv(false);goTo(i,i<idx);}); ovg.appendChild(c);
1192	});
1193	function update(){
1194	  counter.textContent=(idx+1)+' / '+TOTAL;
1195	  pbar.style.width=(idx/(TOTAL-1)*100)+'%';
1196	  [].forEach.call(dotsBox.children,function(d,i){d.classList.toggle('on',i===idx);});
1197	  [].forEach.call(ovg.children,function(c,i){c.classList.toggle('on',i===idx);});
1198	  var s=slides[idx];
1199	  var onLight=s.dataset.theme==='light' && root.dataset.themeMode!=='dark';
1200	  brand.classList.toggle('on-light',onLight);
1201	  if (FIELD) FIELD.setMode(s.dataset.theme==='dark' || root.dataset.themeMode==='dark', !!s.dataset.divider || s.classList.contains('t-cover'));
1202	  deck.style.setProperty('--field-a', s.dataset.divider ? .9 : 1);
1203	}
1204	function goTo(n,back){
1205	  n=Math.max(0,Math.min(TOTAL-1,n));
1206	  if (n===idx) return;
1207	  document.body.classList.toggle('back',!!back);
1208	  slides[idx].classList.remove('active'); idx=n; slides[idx].classList.add('active');
1209	  update(); hideTip();
1210	  setTimeout(function(){document.body.classList.remove('back');},620);
1211	}
1212	function next(){goTo(idx+1,false);} function prev(){goTo(idx-1,true);}
1213	document.getElementById('btnNext').addEventListener('click',next);
1214	document.getElementById('btnPrev').addEventListener('click',prev);
1215	var ov=document.getElementById('ov');
1216	function toggleOv(on){ ov.classList.toggle('on', on===undefined ? !ov.classList.contains('on') : on); }
1217	document.getElementById('btnOv').addEventListener('click',function(){toggleOv();});
1218	function toggleTheme(){ root.dataset.themeMode = root.dataset.themeMode==='dark' ? 'light' : 'dark'; update(); }
1219	document.getElementById('btnTheme').addEventListener('click',toggleTheme);
1220	function toggleFs(){ try{ if(!document.fullscreenElement) document.documentElement.requestFullscreen(); else document.exitFullscreen(); }catch(e){} }
1221	document.getElementById('btnFs').addEventListener('click',toggleFs);
1222	document.addEventListener('keydown',function(e){
1223	  if (e.target && (e.target.tagName==='INPUT'||e.target.tagName==='TEXTAREA')) return;
1224	  if (root.classList.contains('mobile')) return;
1225	  var k=e.key;
1226	  if (k==='ArrowRight'||k==='PageDown'||k===' '){e.preventDefault();next();}
1227	  else if (k==='ArrowLeft'||k==='PageUp'){e.preventDefault();prev();}
1228	  else if (k==='Home'){goTo(0,true);} else if (k==='End'){goTo(TOTAL-1,false);}
1229	  else if (k==='o'||k==='O'){toggleOv();} else if (k==='Escape'){toggleOv(false);}
1230	  else if (k==='d'||k==='D'){toggleTheme();} else if (k==='f'||k==='F'){toggleFs();}
1231	});
1232	var tx=null;
1233	deck.addEventListener('touchstart',function(e){tx=e.touches[0].clientX;},{passive:true});
1234	deck.addEventListener('touchend',function(e){ if(tx===null||root.classList.contains('mobile'))return; var dx=e.changedTouches[0].clientX-tx; if(Math.abs(dx)>50){dx<0?next():prev();} tx=null; });
1235	
1236	/* ---------- tooltip de hover (barras, pontos, segmentos) ---------- */
1237	var tip=document.getElementById('tip');
1238	function showTip(html,x,y){ tip.innerHTML=html; tip.classList.add('on');
1239	  var w=tip.offsetWidth,h=tip.offsetHeight; var px=x+14, py=y-h-12;
1240	  if (px+w>window.innerWidth-8) px=x-w-14; if (py<8) py=y+16; tip.style.left=px+'px'; tip.style.top=py+'px'; }
1241	function hideTip(){ tip.classList.remove('on'); }
1242	document.addEventListener('mousemove',function(e){
1243	  var t=e.target.closest ? e.target.closest('[data-tip]') : null;
1244	  if (t) showTip(t.getAttribute('data-tip'),e.clientX,e.clientY); else if (!e.target.closest('svg.line')) hideTip();
1245	});
1246	
1247	/* ---------- gráfico de linha: abstenção ---------- */
1248	function lineChart(svg,data,opt){
1249	  var W=640,H=420,L=48,R=24,T=20,B=36, NS='http://www.w3.org/2000/svg';
1250	  var x=function(i){return L+i*(W-L-R)/(data.length-1);}, y=function(v){return T+(opt.max-v)/(opt.max-opt.min)*(H-T-B);};
1251	  function el(n,a){var e=document.createElementNS(NS,n);for(var k in a)e.setAttribute(k,a[k]);svg.appendChild(e);return e;}
1252	  opt.ticks.forEach(function(t){ el('line',{x1:L,x2:W-R,y1:y(t),y2:y(t),'class':'gl'}); var tx=el('text',{x:L-8,y:y(t)+4,'text-anchor':'end','class':'ax'}); tx.textContent=t.toString().replace('.',',')+'%'; });
1253	  if (opt.ref){ el('line',{x1:L,x2:W-R,y1:y(opt.ref.v),y2:y(opt.ref.v),'class':'ref'}); var rt=el('text',{x:W-R,y:y(opt.ref.v)-6,'text-anchor':'end','class':'ax'}); rt.textContent=opt.ref.label; }
1254	  data.forEach(function(d,i){ var t=el('text',{x:x(i),y:H-10,'text-anchor':'middle','class':'ax'}); t.textContent=d.k; });
1255	  el('path',{d:data.map(function(d,i){return (i?'L':'M')+x(i).toFixed(1)+' '+y(d.v).toFixed(1);}).join(' '),'class':'ln'});
1256	  var xh=el('line',{y1:T,y2:H-B,'class':'xh'});
1257	  data.forEach(function(d,i){ el('circle',{cx:x(i),cy:y(d.v),r:i===data.length-1?6:4.5,'class':'mk'+(i===data.length-1?' last':'')}); });
1258	  var lb=el('text',{x:x(data.length-1)-10,y:y(data[data.length-1].v)+22,'text-anchor':'end','class':'lbl'}); lb.textContent='21,08% em 2026';
1259	  var lb2=el('text',{x:x(1),y:y(data[1].v)+22,'text-anchor':'middle','class':'lbl'}); lb2.textContent='16,75%';
1260	  var hit=el('rect',{x:L,y:T,width:W-L-R,height:H-T-B,'class':'hit'});
1261	  hit.addEventListener('mousemove',function(e){
1262	    var r=svg.getBoundingClientRect(), px=(e.clientX-r.left)/r.width*W;
1263	    var i=Math.round((px-L)/((W-L-R)/(data.length-1))); i=Math.max(0,Math.min(data.length-1,i));
1264	    xh.setAttribute('x1',x(i)); xh.setAttribute('x2',x(i)); xh.style.opacity=1;
1265	    showTip('<b>'+data[i].k+'</b><br>Abstenção: '+data[i].v.toFixed(2).replace('.',',')+'%',e.clientX,e.clientY);
1266	  });
1267	  hit.addEventListener('mouseleave',function(){xh.style.opacity=0;hideTip();});
1268	}
1269	lineChart(document.getElementById('absChart'),
1270	  [{k:'2002',v:17.74},{k:'2006',v:16.75},{k:'2010',v:18.12},{k:'2014',v:19.39},{k:'2018',v:20.33},{k:'2022',v:20.89},{k:'2026',v:21.08}],
1271	  {min:15,max:22.5,ticks:[16,18,20,22],ref:{v:21.49,label:'1998: 21,49%'}});
1272	
1273	/* ---------- campo animado (pontos à deriva) atrás dos slides escuros ---------- */
1274	var FIELD=(function(){
1275	  var cv=document.getElementById('field'); if(!cv||!cv.getContext) return null;
1276	  var ctx=cv.getContext('2d'), DPR=Math.min(window.devicePixelRatio||1,1.6), W=1600,H=900;
1277	  cv.width=W*DPR; cv.height=H*DPR; ctx.scale(DPR,DPR);
1278	  var N=900, pts=[], running=false, show=true, ring=true, t0=0;
1279	  var reduce=window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
1280	  for (var i=0;i<N;i++){
1281	    var z=Math.random()*.8+.2, a=Math.random()*Math.PI*2, rr=i%3===0?230:(i%3===1?150:320);
1282	    pts.push({x:Math.random()*W,y:Math.random()*H,z:z,vx:(Math.random()-.5)*.35,vy:(Math.random()-.5)*.22,
1283	      ring:i<N*.42, tx:1230+Math.cos(a)*rr*(0.96+Math.random()*.08), ty:440+Math.sin(a)*rr*(0.96+Math.random()*.08), ph:Math.random()*6.28});
1284	  }
1285	  function frame(ts){
1286	    if (!running) return;
1287	    var t=ts/1000; ctx.clearRect(0,0,W,H);
1288	    for (var i=0;i<N;i++){
1289	      var p=pts[i];
1290	      if (ring && p.ring){
1291	        var ang=t*.05*(p.z>.6?1:-1), cx=1230, cy=440, dx=p.tx-cx, dy=p.ty-cy;
1292	        var gx=cx+dx*Math.cos(ang)-dy*Math.sin(ang), gy=cy+dx*Math.sin(ang)+dy*Math.cos(ang);
1293	        p.x+=(gx-p.x)*.03; p.y+=(gy-p.y)*.03;
1294	      } else {
1295	        p.x+=p.vx*p.z*1.4; p.y+=p.vy*p.z*1.4;
1296	        if(p.x<-10)p.x=W+10; if(p.x>W+10)p.x=-10; if(p.y<-10)p.y=H+10; if(p.y>H+10)p.y=-10;
1297	      }
